import lzma
import re

_MAGIC = b'FZ1'
_HEX = re.compile(rb'[0-9a-f]+\Z')
_B36 = re.compile(rb'[a-z0-9]+\Z')


def _putvar(n):
    out = bytearray()
    while n >= 128:
        out.append((n & 127) | 128)
        n >>= 7
    out.append(n)
    return out


def _getvar(data, pos):
    n = shift = 0
    while True:
        b = data[pos]
        pos += 1
        n |= (b & 127) << shift
        if not b & 128:
            return n, pos
        shift += 7


def _transform(data):
    out = bytearray()
    # Split on LF, retaining whether each segment was terminated.
    parts = data.split(b'\n')
    terminated = data.endswith(b'\n')
    if terminated:
        parts.pop()
    for body in parts:
        if _HEX.fullmatch(body) and len(body) % 2 == 0:
            typ = 1
            payload = bytes.fromhex(body.decode('ascii'))
        elif _B36.fullmatch(body):
            typ = 2
            n = int(body, 36)
            payload = n.to_bytes((n.bit_length() + 7) // 8, 'big')
            payload = _putvar(len(payload)) + payload
        else:
            typ = 0
            payload = body
        out.append(typ)
        out += _putvar(len(body))
        out += _putvar(len(payload))
        out += payload
    out.append(4 if terminated else 0)  # end marker; distinguishes final LF
    return bytes(out)


def _inverse(data):
    result = bytearray()
    pos = 0
    while pos < len(data):
        typ = data[pos]
        pos += 1
        if typ == 4:
            result += b'\n'
            if pos != len(data):
                raise ValueError('trailing data')
            break
        length, pos = _getvar(data, pos)
        plen, pos = _getvar(data, pos)
        payload = data[pos:pos + plen]
        pos += plen
        if len(payload) != plen:
            raise ValueError('truncated data')
        if typ == 0:
            body = payload
        elif typ == 1:
            body = payload.hex().encode('ascii')
        elif typ == 2:
            sz, q = _getvar(payload, 0)
            num = int.from_bytes(payload[q:q + sz], 'big')
            s = ''
            while num:
                num, r = divmod(num, 36)
                s = '0123456789abcdefghijklmnopqrstuvwxyz'[r] + s
            body = s.rjust(length, '0').encode('ascii')
        else:
            raise ValueError('bad token')
        if len(body) != length:
            raise ValueError('bad length')
        result += body + b'\n'
    # The encoded stream always has an end marker. It emits the newline iff needed;
    # remove the segment delimiter added by the loop for a non-terminated input.
    if not data or data[-1] != 4:
        raise ValueError('missing end marker')
    if data[-1] == 4:
        # end marker's low bit encodes the source trailing-newline state in v1
        pass
    return bytes(result)


def enc(data):
    transformed = _transform(data)
    packed = lzma.compress(transformed, format=lzma.FORMAT_XZ, preset=9)
    # Store a compact tagged representation. The raw option handles incompressible data.
    if len(packed) < len(data):
        return _MAGIC + b'\x01' + packed
    return _MAGIC + b'\x00' + data


def dec(data):
    if not data.startswith(_MAGIC) or len(data) < 4:
        return data
    mode = data[3]
    payload = data[4:]
    if mode == 0:
        return payload
    if mode == 1:
        return _inverse(lzma.decompress(payload))
    return data

